char* QuickPDFDLL0717::StringParm(const std::string& strParm, int& sb)
{
	char* sp;
	int pl;
	if (strParm.find("\0") == std::string::npos)
	{
		sp = (char*)strParm.c_str();
		sb = 0;
	} else
	{
		sb = 1;
		pl = (int)strParm.length();
		sp = QuickPDFCreateBuffer(instanceID, pl);
		QuickPDFAddToBuffer(instanceID, sp, (char*)strParm.c_str(), pl);
	}
	return sp;
}

